$securityDir = "d:\E-Commerce\backend\src\main\java\com\ecommerce\security"
New-Item -ItemType Directory -Force -Path $securityDir | Out-Null

$classes = @(
    @{ Name = "UserDetailsImpl"; Content = "package com.ecommerce.security;`nimport com.ecommerce.models.User;`nimport org.springframework.security.core.GrantedAuthority;`nimport org.springframework.security.core.authority.SimpleGrantedAuthority;`nimport org.springframework.security.core.userdetails.UserDetails;`nimport java.util.Collection;`nimport java.util.List;`npublic class UserDetailsImpl implements UserDetails {`n    private Long id;`n    private String email;`n    private String password;`n    private Collection<? extends GrantedAuthority> authorities;`n    public UserDetailsImpl(Long id, String email, String password, Collection<? extends GrantedAuthority> authorities) {`n        this.id = id;`n        this.email = email;`n        this.password = password;`n        this.authorities = authorities;`n    }`n    public static UserDetailsImpl build(User user) {`n        List<GrantedAuthority> authorities = List.of(new SimpleGrantedAuthority(user.getRole().name()));`n        return new UserDetailsImpl(`n                user.getId(),`n                user.getEmail(),`n                user.getPassword(),`n                authorities);`n    }`n    public Long getId() { return id; }`n    @Override`n    public Collection<? extends GrantedAuthority> getAuthorities() { return authorities; }`n    @Override`n    public String getPassword() { return password; }`n    @Override`n    public String getUsername() { return email; }`n    @Override`n    public boolean isAccountNonExpired() { return true; }`n    @Override`n    public boolean isAccountNonLocked() { return true; }`n    @Override`n    public boolean isCredentialsNonExpired() { return true; }`n    @Override`n    public boolean isEnabled() { return true; }`n}" },
    @{ Name = "UserDetailsServiceImpl"; Content = "package com.ecommerce.security;`nimport com.ecommerce.models.User;`nimport com.ecommerce.repositories.UserRepository;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.security.core.userdetails.UserDetails;`nimport org.springframework.security.core.userdetails.UserDetailsService;`nimport org.springframework.security.core.userdetails.UsernameNotFoundException;`nimport org.springframework.stereotype.Service;`n@Service`n@RequiredArgsConstructor`npublic class UserDetailsServiceImpl implements UserDetailsService {`n    private final UserRepository userRepository;`n    @Override`n    public UserDetails loadUserByUsername(String email) throws UsernameNotFoundException {`n        User user = userRepository.findByEmail(email)`n                .orElseThrow(() -> new UsernameNotFoundException(`"User Not Found with email: `" + email));`n        return UserDetailsImpl.build(user);`n    }`n}" },
    @{ Name = "JwtUtils"; Content = "package com.ecommerce.security;`nimport io.jsonwebtoken.*;`nimport io.jsonwebtoken.security.Keys;`nimport org.springframework.beans.factory.annotation.Value;`nimport org.springframework.security.core.Authentication;`nimport org.springframework.stereotype.Component;`nimport java.security.Key;`nimport java.util.Date;`n@Component`npublic class JwtUtils {`n    @Value(`"`${app.jwt.secret}`")`n    private String jwtSecret;`n    @Value(`"`${app.jwt.expirationMs}`")`n    private int jwtExpirationMs;`n    private Key key() {`n        return Keys.hmacShaKeyFor(io.jsonwebtoken.io.Decoders.BASE64.decode(jwtSecret));`n    }`n    public String generateJwtToken(Authentication authentication) {`n        UserDetailsImpl userPrincipal = (UserDetailsImpl) authentication.getPrincipal();`n        return Jwts.builder()`n                .setSubject((userPrincipal.getUsername()))`n                .setIssuedAt(new Date())`n                .setExpiration(new Date((new Date()).getTime() + jwtExpirationMs))`n                .signWith(key(), SignatureAlgorithm.HS256)`n                .compact();`n    }`n    public String getUserNameFromJwtToken(String token) {`n        return Jwts.parserBuilder().setSigningKey(key()).build()`n                .parseClaimsJws(token).getBody().getSubject();`n    }`n    public boolean validateJwtToken(String authToken) {`n        try {`n            Jwts.parserBuilder().setSigningKey(key()).build().parse(authToken);`n            return true;`n        } catch (JwtException e) {`n            // log error`n        }`n        return false;`n    }`n}" },
    @{ Name = "JwtAuthFilter"; Content = "package com.ecommerce.security;`nimport jakarta.servlet.FilterChain;`nimport jakarta.servlet.ServletException;`nimport jakarta.servlet.http.HttpServletRequest;`nimport jakarta.servlet.http.HttpServletResponse;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.security.authentication.UsernamePasswordAuthenticationToken;`nimport org.springframework.security.core.context.SecurityContextHolder;`nimport org.springframework.security.core.userdetails.UserDetails;`nimport org.springframework.security.web.authentication.WebAuthenticationDetailsSource;`nimport org.springframework.stereotype.Component;`nimport org.springframework.util.StringUtils;`nimport org.springframework.web.filter.OncePerRequestFilter;`nimport java.io.IOException;`n@Component`n@RequiredArgsConstructor`npublic class JwtAuthFilter extends OncePerRequestFilter {`n    private final JwtUtils jwtUtils;`n    private final UserDetailsServiceImpl userDetailsService;`n    @Override`n    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)`n            throws ServletException, IOException {`n        try {`n            String jwt = parseJwt(request);`n            if (jwt != null && jwtUtils.validateJwtToken(jwt)) {`n                String username = jwtUtils.getUserNameFromJwtToken(jwt);`n                UserDetails userDetails = userDetailsService.loadUserByUsername(username);`n                UsernamePasswordAuthenticationToken authentication =`n                        new UsernamePasswordAuthenticationToken(`n                                userDetails,`n                                null,`n                                userDetails.getAuthorities());`n                authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));`n                SecurityContextHolder.getContext().setAuthentication(authentication);`n            }`n        } catch (Exception e) {}`n        filterChain.doFilter(request, response);`n    }`n    private String parseJwt(HttpServletRequest request) {`n        String headerAuth = request.getHeader(`"Authorization`");`n        if (StringUtils.hasText(headerAuth) && headerAuth.startsWith(`"Bearer `")) {`n            return headerAuth.substring(7);`n        }`n        return null;`n    }`n}" },
    @{ Name = "SecurityConfig"; Content = "package com.ecommerce.security;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.context.annotation.Bean;`nimport org.springframework.context.annotation.Configuration;`nimport org.springframework.security.authentication.AuthenticationManager;`nimport org.springframework.security.authentication.dao.DaoAuthenticationProvider;`nimport org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;`nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;`nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;`nimport org.springframework.security.config.http.SessionCreationPolicy;`nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;`nimport org.springframework.security.crypto.password.PasswordEncoder;`nimport org.springframework.security.web.SecurityFilterChain;`nimport org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;`n@Configuration`n@EnableMethodSecurity`n@RequiredArgsConstructor`npublic class SecurityConfig {`n    private final UserDetailsServiceImpl userDetailsService;`n    private final JwtAuthFilter authFilter;`n    @Bean`n    public DaoAuthenticationProvider authenticationProvider() {`n        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();`n        authProvider.setUserDetailsService(userDetailsService);`n        authProvider.setPasswordEncoder(passwordEncoder());`n        return authProvider;`n    }`n    @Bean`n    public AuthenticationManager authenticationManager(AuthenticationConfiguration authConfig) throws Exception {`n        return authConfig.getAuthenticationManager();`n    }`n    @Bean`n    public PasswordEncoder passwordEncoder() {`n        return new BCryptPasswordEncoder();`n    }`n    @Bean`n    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {`n        http.csrf(csrf -> csrf.disable())`n            .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))`n            .authorizeHttpRequests(auth -> `n                auth.requestMatchers(`"/api/auth/**`").permitAll()`n                    .requestMatchers(`"/v3/api-docs/**`", `"/swagger-ui/**`", `"/swagger-ui.html`").permitAll()`n                    .requestMatchers(`"/api/products/**`").permitAll()`n                    .anyRequest().authenticated()`n            );`n        http.authenticationProvider(authenticationProvider());`n        http.addFilterBefore(authFilter, UsernamePasswordAuthenticationFilter.class);`n        return http.build();`n    }`n}" }
)

foreach ($class in $classes) {
    $path = "$securityDir\$($class.Name).java"
    Set-Content -Path $path -Value $class.Content -Encoding UTF8
}
